def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0:
        return 0.0
    props = s.get('element_properties', {})
    total = 0.0
    weight = 0.0
    for e, x in s.get('composition', {}).items():
        r = props.get(e, {}).get('covalent_radius_A')
        if x is not None and x > 0 and r is not None and math.isfinite(r) and r > 0:
            total += x * r ** 3
            weight += x
    if weight <= 0:
        return 0.0
    return float(4.0 * math.pi * total / (3.0 * weight * v))

def feature(s):
    sites = s.get('sites', [])
    n = len(sites)
    if n == 0:
        return 0.0
    occ = [max(0.0, t.get('occupancy', 1.0) or 0.0) for t in sites]
    nearest = [math.inf for i in range(n)]
    neighbors = s.get('neighbors', [])
    for b in neighbors:
        i = b['i']
        j = b['j']
        d = b.get('distance_A')
        if d is not None and d > 0 and occ[i] > 0 and occ[j] > 0 and d < nearest[i]:
            nearest[i] = d
    coordination = [0.0 for i in range(n)]
    for b in neighbors:
        i = b['i']
        j = b['j']
        d = b.get('distance_A')
        if d is not None and d > 0 and occ[i] > 0 and occ[j] > 0 and d <= 1.25 * nearest[i]:
            coordination[i] += occ[j]
    weight = sum(occ)
    if weight <= 0:
        return 0.0
    mean = sum(occ[i] * coordination[i] for i in range(n)) / weight
    if mean <= 0:
        return 0.0
    variance = sum(occ[i] * (coordination[i] - mean) ** 2 for i in range(n)) / weight
    return float(math.sqrt(max(0.0, variance)) / mean)

def feature(s):
    sites = s.get('sites', [])
    n = len(sites)
    if n == 0:
        return 0.0
    occ = [max(0.0, t.get('occupancy', 1.0) or 0.0) for t in sites]
    nearest = [math.inf for i in range(n)]
    for b in s.get('neighbors', []):
        i = b['i']
        j = b['j']
        d = b.get('distance_A')
        if d is not None and d > 0 and occ[i] > 0 and occ[j] > 0 and d < nearest[i]:
            nearest[i] = d
    weight = sum(occ[i] for i in range(n) if math.isfinite(nearest[i]))
    if weight <= 0:
        return 0.0
    mean = sum(occ[i] * nearest[i] for i in range(n) if math.isfinite(nearest[i])) / weight
    if mean <= 0:
        return 0.0
    variance = sum(occ[i] * (nearest[i] - mean) ** 2 for i in range(n) if math.isfinite(nearest[i])) / weight
    return float(math.sqrt(max(0.0, variance)) / mean)

def feature(s):
    sites = s.get('sites', [])
    if len(sites) == 0:
        return 0.0
    props = s.get('element_properties', {})
    chi = [props.get(t.get('element'), {}).get('eneg') for t in sites]
    occ = [max(0.0, t.get('occupancy', 1.0) or 0.0) for t in sites]
    atoms = sum(occ)
    if atoms <= 0:
        return 0.0
    total = 0.0
    for b in s.get('neighbors', []):
        i = b['i']
        j = b['j']
        d = b.get('distance_A')
        if d is not None and 0 < d < 6.0 and chi[i] is not None and chi[j] is not None:
            delta = chi[i] - chi[j]
            taper = 1.0 - d / 6.0
            total += occ[i] * occ[j] * delta * delta * taper * taper / d
    return float(0.5 * total / atoms)

def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0:
        return 0.0
    props = s.get('element_properties', {})
    total = 0.0
    weight = 0.0
    for e, x in s.get('composition', {}).items():
        z = props.get(e, {}).get('valence_electrons')
        if x is not None and x > 0 and z is not None and math.isfinite(z):
            total += x * z
            weight += x
    return float(total / (weight * v)) if weight > 0 else 0.0
